arguments.file_text:
@if (Products.Count == 0)
{
    <div class="empty-results">
        <p>No products found matching your criteria.</p>
    </div>
}
else
{
    <div class="product-grid">
        @foreach (var product in Products)
        {
            <ProductCard Product="product"
                         OnProductSelected="OnProductSelected"
                         OnAddToCart="OnAddToCart" />
        }
    </div>
}

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = [];

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button class="btn-page" disabled="@(Page <= 1)" @onclick="@(() => GoToPage(Page - 1))">
            Previous
        </button>

        @foreach (var p in GetPageNumbers())
        {
            <button class="btn-page @(p == Page ? "active" : "")"
                    @onclick="@(() => GoToPage(p))">
                @p
            </button>
        }

        <button class="btn-page" disabled="@(Page >= TotalPages)" @onclick="@(() => GoToPage(Page + 1))">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != Page)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private IEnumerable<int> GetPageNumbers()
    {
        // Show up to 7 page buttons centered around the current page
        const int maxVisible = 7;
        int start, end;

        if (TotalPages <= maxVisible)
        {
            start = 1;
            end = TotalPages;
        }
        else
        {
            int half = maxVisible / 2;
            start = Math.Max(1, Page - half);
            end = start + maxVisible - 1;
            if (end > TotalPages)
            {
                end = TotalPages;
                start = end - maxVisible + 1;
            }
        }

        return Enumerable.Range(start, end - start + 1);
    }
}

